html[data-lumen-theme="midnight"] .sheets-list{max-width:none}
html[data-lumen-theme="midnight"] .sheetlist-h{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:0 2px 12px;font:650 14.5px var(--sans);letter-spacing:-.01em;color:var(--ink)}
html[data-lumen-theme="midnight"] .sheet-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px}
html[data-lumen-theme="midnight"] .sheet-card{text-align:left;border:1px solid var(--line);border-radius:var(--r);background:var(--panel);cursor:pointer;padding:15px 16px;display:flex;flex-direction:column;gap:5px;font-family:inherit;width:100%;box-shadow:var(--shadow);transition:border-color .15s var(--ease),box-shadow .15s var(--ease),transform .12s var(--ease)}
html[data-lumen-theme="midnight"] .sheet-card:hover{border-color:var(--faint);box-shadow:var(--shadow-2);transform:translateY(-1px)}
html[data-lumen-theme="midnight"] .sheet-card.on{border-color:var(--pine);box-shadow:0 0 0 3px var(--ring)}
html[data-lumen-theme="midnight"] .sheet-card.on .sc-name{color:var(--pine-strong);font-weight:680}
html[data-lumen-theme="midnight"] .sc-name{font-size:13.5px;color:var(--ink);font-weight:640;letter-spacing:-.005em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
html[data-lumen-theme="midnight"] .sc-meta{font:600 10px var(--mono);letter-spacing:.04em;color:var(--faint);display:flex;gap:7px;align-items:center;flex-wrap:wrap}
html[data-lumen-theme="midnight"] .sc-fu{background:var(--teal-tint);color:var(--teal);padding:1px 7px;border-radius:999px}
html[data-lumen-theme="midnight"] .sheet-editor{display:none;position:fixed;inset:0;z-index:80;background:#EEEFE9;flex-direction:column}
/* the grid canvas is always light, so the editor keeps light tokens */
html[data-lumen-theme="midnight"] .sheet-editor{--panel:#EEEFE9;--panel-2:#EEEFE9;--sink:#EEEFE9;--ink:#19202e;--ink-2:#1f2b41;--muted:#283d62;--faint:#B6BDCF;--line:#EEEFE9;--line-2:#EEEFE9;--pine:#283d62;--pine-strong:#26385a;--pine-tint:#EEEFE9;--ring:rgba(163,133,63,.18);--on-accent:#EEEFE9;--grad-btn:#EEEFE9;--grad-btn-hi:#EEEFE9;--btn-line:#EEEFE9;--btn-ink:#1f2b41;--edge:rgba(255,255,255,.7);--field:#EEEFE9;--field-line:#EEEFE9;--bad:#283d62;--bad-tint:#EEEFE9;--bad-line:#EEEFE9;--card-line:#EEEFE9;--gold-dim:rgba(163,133,63,.12);--gold-glow:rgba(163,133,63,.25)}
html[data-lumen-theme="midnight"] .sheet-editor.show{display:flex}
html[data-lumen-theme="midnight"] .se-bar{display:flex;align-items:center;gap:10px;padding:10px 16px;border-bottom:1px solid var(--line);background:#EEEFE9;flex:none}
html[data-lumen-theme="midnight"] .se-back{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:#EEEFE9;border-radius:9px;padding:7px 14px;font:600 13px var(--sans);color:var(--ink-2);cursor:pointer;transition:.15s var(--ease)}
html[data-lumen-theme="midnight"] .se-back:hover{background:var(--panel-2);border-color:var(--faint)}
html[data-lumen-theme="midnight"] .se-name{font:650 15px var(--sans);color:var(--ink);letter-spacing:-.01em}
html[data-lumen-theme="midnight"] .se-bar .sp{flex:1}
html[data-lumen-theme="midnight"] .se-bar .savestate{font:600 11px var(--mono);color:var(--faint)}
html[data-lumen-theme="midnight"] .fx-bar{display:flex;align-items:stretch;background:#EEEFE9;border-bottom:1px solid var(--line);flex:none;height:34px}
html[data-lumen-theme="midnight"] .fx-name{width:88px;flex:none;font:500 12.5px var(--sans);color:var(--ink-2);border-right:1px solid var(--line);display:grid;place-items:center}
html[data-lumen-theme="midnight"] .fx-lbl{font:italic 600 12.5px Georgia,serif;color:var(--faint);display:grid;place-items:center;padding:0 13px}
html[data-lumen-theme="midnight"] .fx-input{flex:1;border:0;background:none;box-shadow:none;border-radius:0;padding:0 12px;font:13px var(--sans);color:var(--ink)}
html[data-lumen-theme="midnight"] .fx-input:focus{outline:none;border:0;box-shadow:none}
html[data-lumen-theme="midnight"] .xs-addrows{position:absolute;left:152px;bottom:16px;z-index:15;border:1px solid var(--line);background:#EEEFE9;border-radius:999px;padding:6px 14px;font:600 12px var(--sans);color:var(--ink-2);cursor:pointer;box-shadow:var(--shadow-2);transition:.15s var(--ease)}
html[data-lumen-theme="midnight"] .xs-addrows:hover{background:var(--panel-2)}
html[data-lumen-theme="midnight"] .xs-viewport{flex:1;width:100%;min-height:0;position:relative;overflow:auto}
html[data-lumen-theme="midnight"] .xs-host{width:100%;height:100%;transform-origin:top left}
html[data-lumen-theme="midnight"] .xs-zoom{position:absolute;left:16px;bottom:16px;z-index:15;display:flex;align-items:center;gap:2px;background:#EEEFE9;border:1px solid var(--line);border-radius:999px;padding:4px 6px;box-shadow:var(--shadow-2)}
html[data-lumen-theme="midnight"] .xs-zoom-btn{width:24px;height:24px;border:0;background:none;border-radius:50%;font:600 15px var(--sans);color:var(--ink-2);cursor:pointer;display:grid;place-items:center;line-height:1;padding:0}
html[data-lumen-theme="midnight"] .xs-zoom-btn:hover{background:var(--sink)}
html[data-lumen-theme="midnight"] .xs-zoom-btn:disabled{opacity:.35;cursor:default}
html[data-lumen-theme="midnight"] .xs-zoom-pct{font:600 11.5px var(--mono);color:var(--muted);min-width:38px;text-align:center;user-select:none}
html[data-lumen-theme="midnight"] body.editing-sheet{overflow:hidden}
/* Sheets: Google-Sheets-leaning restyle of the x-spreadsheet chrome (DOM
   only - the grid itself is canvas-rendered by the vendored library and
   can't be restyled by CSS). Scoped to #xs-host. */
html[data-lumen-theme="midnight"] #xs-host,html[data-lumen-theme="midnight"] #xs-host input,html[data-lumen-theme="midnight"] #xs-host select,html[data-lumen-theme="midnight"] #xs-host textarea{font-family:var(--sans)}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-toolbar,html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-bottombar{background:#EEEFE9}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-toolbar{border-bottom:1px solid var(--line)}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-bottombar{border-top:1px solid var(--line)}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-toolbar .x-spreadsheet-toolbar-btn{border-radius:6px}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-toolbar .x-spreadsheet-toolbar-btn:hover,html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-toolbar .x-spreadsheet-toolbar-btn.active{background:var(--sink)}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-toolbar-divider{border-right-color:var(--line)}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-menu>li{color:var(--muted);font-family:var(--sans);font-weight:600}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-menu>li.active{background:var(--pine-tint);color:var(--pine-strong)}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-bottombar .x-spreadsheet-menu>li{border-right-color:var(--line)}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-selector .x-spreadsheet-selector-area{border-color:var(--pine);background:rgba(160,124,45,.10)}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-selector .x-spreadsheet-selector-corner{background:var(--pine);border-color:#EEEFE9}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-selector .x-spreadsheet-selector-clipboard{border-color:var(--pine)}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-scrollbar{background-color:var(--panel-2)}
html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-scrollbar.horizontal>div,html[data-lumen-theme="midnight"] #xs-host .x-spreadsheet-scrollbar.vertical>div{background:#EEEFE9}

/* ===== follow-up modal ===== */
html[data-lumen-theme="midnight"] .fu-ov{display:none;position:fixed;inset:0;z-index:95;background:rgba(14,22,17,.5);place-items:center;backdrop-filter:blur(2px)}
html[data-lumen-theme="midnight"] .fu-ov.show{display:grid}
html[data-lumen-theme="midnight"] .fu-card{background:var(--grad-card);border:1px solid var(--btn-line);border-radius:var(--r-lg);padding:26px 26px 22px;width:min(540px,92vw);max-height:88vh;overflow:auto;box-shadow:var(--shadow-3);position:relative}
html[data-lumen-theme="midnight"] .fu-card h2{font-family:var(--sans);font-size:19px;font-weight:700;letter-spacing:-.02em;margin:0 0 6px;color:var(--ink)}
html[data-lumen-theme="midnight"] .fu-x{position:absolute;top:12px;right:14px;border:0;background:none;font-size:22px;line-height:1;color:var(--faint);cursor:pointer;padding:4px;border-radius:6px}
html[data-lumen-theme="midnight"] .fu-x:hover{background:var(--sink);color:var(--ink)}
html[data-lumen-theme="midnight"] .fu-note{font-size:12.5px;color:var(--muted);background:var(--panel-2);border:1px solid var(--line-2);border-radius:9px;padding:9px 11px;margin:0 0 14px;line-height:1.5}
html[data-lumen-theme="midnight"] .fu-tok{font:600 11px var(--mono);color:var(--faint);margin:6px 0 16px}
html[data-lumen-theme="midnight"] .fu-actions{display:flex;gap:9px;flex-wrap:wrap}
html[data-lumen-theme="midnight"] .fu-result{margin-top:16px;border-top:1px solid var(--line-2);padding-top:13px}
html[data-lumen-theme="midnight"] .fu-sum{font-size:13px;color:var(--ink-2);margin-bottom:10px}
html[data-lumen-theme="midnight"] .fu-man-h{font:600 11px var(--mono);letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin:8px 0 6px}
html[data-lumen-theme="midnight"] .fu-man{display:flex;gap:10px;align-items:center;padding:7px 0;border-bottom:1px solid var(--line-2);font-size:13px}
html[data-lumen-theme="midnight"] .fu-man .fm-name{flex:1;color:var(--ink-2);font-weight:580}
html[data-lumen-theme="midnight"] .fu-man .fm-ch{font:600 10px var(--mono);background:var(--teal-tint);color:var(--teal);padding:2px 7px;border-radius:999px}
html[data-lumen-theme="midnight"] .fu-man .fm-ph{font:12px var(--mono);color:var(--muted)}

/* ===== website builder / embedded frames ===== */
html[data-lumen-theme="midnight"] #v-website-builder.view.on{max-width:none;height:100%;display:flex;flex-direction:column}
html[data-lumen-theme="midnight"] .wb-wrap{position:relative;flex:1;min-height:560px;height:calc(100vh - 210px);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;background:#171c27;box-shadow:var(--shadow)}
html[data-lumen-theme="midnight"] .wb-frame{position:absolute;inset:0;width:100%;height:100%;border:0;display:block;background:#171c27}
html[data-lumen-theme="midnight"] .wb-loading,html[data-lumen-theme="midnight"] .wb-error{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;text-align:center;padding:30px;background:var(--panel)}
html[data-lumen-theme="midnight"] .wb-loadtxt{font:650 15px var(--sans);color:var(--ink-2)}
html[data-lumen-theme="midnight"] .wb-loadsub,html[data-lumen-theme="midnight"] .wb-error span{font-size:12.5px;color:var(--muted);max-width:420px}
html[data-lumen-theme="midnight"] .wb-error b{font:650 15px var(--sans);color:var(--bad)}
html[data-lumen-theme="midnight"] .wb-spin{width:34px;height:34px;border-radius:50%;border:3px solid var(--line);border-top-color:var(--pine);animation:wbspin .8s linear infinite}
@keyframes wbspin{to{transform:rotate(360deg)}}

/* ===== floating AI chat ===== */
html[data-lumen-theme="midnight"] .chat-fab{position:fixed;right:24px;bottom:24px;z-index:70;width:52px;height:52px;border-radius:50%;border:0;background:var(--pine);color:var(--on-accent);display:grid;place-items:center;cursor:pointer;box-shadow:0 6px 18px rgba(0,0,0,.4);transition:.18s var(--ease)}
html[data-lumen-theme="midnight"] .chat-fab:hover{background:var(--pine-strong);transform:translateY(-1px)}
html[data-lumen-theme="midnight"] .chat-fab svg{width:22px;height:22px}
html[data-lumen-theme="midnight"] .chat-fab-icon-close{display:none}
html[data-lumen-theme="midnight"] .chat-fab.open .chat-fab-icon-open{display:none}
html[data-lumen-theme="midnight"] .chat-fab.open .chat-fab-icon-close{display:block}
html[data-lumen-theme="midnight"] .chat-panel{position:fixed;right:24px;bottom:88px;z-index:70;width:min(380px,calc(100vw - 32px));height:min(600px,calc(100vh - 120px));background:var(--panel);border:1px solid var(--line);border-radius:var(--r-lg);box-shadow:var(--shadow-3);display:flex;flex-direction:column;overflow:hidden}
html[data-lumen-theme="midnight"] .chat-panel[hidden]{display:none}
html[data-lumen-theme="midnight"] .chat-panel-bar{flex:none;display:flex;align-items:center;justify-content:space-between;padding:12px 14px;border-bottom:1px solid var(--line);background:var(--panel)}
html[data-lumen-theme="midnight"] .chat-panel-title{font:650 13.5px var(--sans);color:var(--ink)}
html[data-lumen-theme="midnight"] .chat-panel-x{border:0;background:none;font-size:22px;line-height:1;color:var(--muted);cursor:pointer;padding:2px 6px;border-radius:6px}
html[data-lumen-theme="midnight"] .chat-panel-x:hover{background:var(--sink);color:var(--ink)}
html[data-lumen-theme="midnight"] .chat-panel .wb-wrap{flex:1;min-height:0;height:auto;border:0;border-radius:0;box-shadow:none}
@media (max-width:480px){html[data-lumen-theme="midnight"] .chat-panel{right:16px;left:16px;bottom:82px;width:auto}html[data-lumen-theme="midnight"] .chat-fab{right:16px;bottom:16px}}
/* First-run walkthrough (Tour) */
html[data-lumen-theme="midnight"] .tb-help{border:1px solid var(--line-2);background:var(--sink);color:var(--muted);width:32px;height:32px;border-radius:var(--r-sm);font:700 var(--fs-md) var(--sans);cursor:pointer;line-height:1;flex:none;display:flex;align-items:center;justify-content:center;transition:color var(--t-fast) var(--ease),border-color var(--t-fast) var(--ease),background var(--t-fast) var(--ease)}
html[data-lumen-theme="midnight"] .tb-help:hover{color:var(--ink);border-color:var(--accent);background:var(--panel-2)}
html[data-lumen-theme="midnight"] .pageintro{position:relative}
html[data-lumen-theme="midnight"] .sect-help{position:absolute;top:0;right:0;display:inline-flex;align-items:center;gap:var(--sp-2);border:1px solid var(--line-2);background:var(--sink);color:var(--muted);font:600 var(--fs-sm) var(--sans);padding:var(--sp-2) var(--sp-3);border-radius:var(--r-pill);cursor:pointer;transition:color var(--t-fast) var(--ease),border-color var(--t-fast) var(--ease),background var(--t-fast) var(--ease)}
html[data-lumen-theme="midnight"] .sect-help:hover{color:var(--ink);border-color:var(--accent);background:var(--panel-2)}
html[data-lumen-theme="midnight"] .sect-help b{font-weight:700;font-size:var(--fs-base)}
html[data-lumen-theme="midnight"] .tour-block{position:fixed;inset:0;z-index:9990;background:transparent}
html[data-lumen-theme="midnight"] .tour-block.dim{background:rgba(10,10,9,.62)}
html[data-lumen-theme="midnight"] .tour-spot{position:fixed;z-index:9991;border-radius:10px;background:transparent;box-shadow:0 0 0 9999px rgba(10,10,9,.62),0 0 0 2px var(--gold,#B6BDCF);transition:box-shadow .15s ease;pointer-events:none}
html[data-lumen-theme="midnight"] .tour-tip{position:fixed;z-index:9992;width:min(324px,calc(100vw - 32px));background:var(--panel,#181e2b);border:1px solid var(--line-2,#1d273b);border-radius:12px;padding:15px 16px 12px;box-shadow:0 18px 50px rgba(0,0,0,.5);color:var(--ink,#EEEFE9)}
html[data-lumen-theme="midnight"] .tour-tip h4{margin:0 0 6px;font:650 15px var(--sans,sans-serif);color:var(--ink,#EEEFE9)}
html[data-lumen-theme="midnight"] .tour-tip p{margin:0 0 13px;font:400 13px/1.55 var(--sans,sans-serif);color:var(--muted,#B6BDCF)}
html[data-lumen-theme="midnight"] .tour-row{display:flex;align-items:center;gap:8px}
html[data-lumen-theme="midnight"] .tour-count{font:500 12px var(--sans,sans-serif);color:var(--faint,#B6BDCF);margin-right:auto}
html[data-lumen-theme="midnight"] .tour-skip{display:block;margin-top:9px;border:0;background:none;color:var(--faint,#B6BDCF);font:500 12px var(--sans,sans-serif);cursor:pointer;padding:4px 2px}
html[data-lumen-theme="midnight"] .tour-skip:hover{color:var(--ink,#EEEFE9)}

/* Lumen / Ink & sage. Deliberate type hierarchy, task-specific work surfaces. */
@font-face{font-family:'DM Sans';src:url('/assets/fonts/dm-sans.ttf') format('truetype');font-weight:100 1000;font-display:swap}
@font-face{font-family:Newsreader;src:url('/assets/fonts/newsreader.ttf') format('truetype');font-weight:200 800;font-display:swap}
html[data-lumen-theme="midnight"]{--sans:'DM Sans',sans-serif;--serif:Newsreader,Georgia,serif;--canvas:#171C27;--bg:#171C27;--panel:#22314d;--panel-2:#1d283d;--field:#1a2130;--field-line:#233350;--line:#202d46;--line-2:#1e2a40;--ink:#EEEFE9;--muted:#B6BDCF;--faint:#B6BDCF;--pine:#D7A31A;--pine-strong:#EEEFE9;--accent:#D7A31A;--gold:#B6BDCF;--pine-wash:#D7A31A13;--teal:#B6BDCF;--teal-tint:#B6BDCF15;--bad:#e3a399;--on-accent:#10141E;--ease:cubic-bezier(.22,.8,.25,1);--grad-head:none}
html[data-lumen-theme="midnight"] body{font-family:var(--sans);font-size:14px;line-height:1.6;font-weight:400;font-optical-sizing:auto;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
