html[data-lumen-theme="ink-light"]{
  /* surfaces — neutral charcoal, always dark */
  --canvas:#f1eee6; --bg:#f1eee6; --panel:#efede7; --panel-2:#eeece7; --sink:#ecebe8;
  --ink:#243044; --ink-2:#243044; --muted:#535D6F; --faint:#535D6F;
  --line:#ebebe9; --line-2:#edece8;
  /* accent gold — used sparingly — + intent */
  --pine:#535D6F; --pine-strong:#535D6F; --pine-deep:#535D6F; --pine-tint:#eeece7; --pine-wash:#efede7;
  --on-accent:#f0eee6;
