  --ok:#283D62; --ok-tint:#edece8;
  --warn:#535D6F; --warn-tint:#eeece7; --warn-line:#e9eae9;
  --bad:#A13A35; --bad-tint:#ecebe8; --bad-line:#e8e9ea;
  /* terminal */
  --forest:#f1eee6; --forest-2:#f0eee6; --forest-ink:#243044; --forest-mut:#535D6F; --forest-line:#ecebe8; --forest-accent:#535D6F;
  /* component tokens */
  --grad-card:#efede7;
  --grad-head:#f0eee6;
  --grad-btn:#edece8;
  --grad-btn-hi:#ecebe8;
  --grad-gold:#535D6F;
  --grad-gold-hi:#535D6F;
  --gold-line:#535D6F;
  --edge:rgba(255,255,255,.03);
  --field:#f1eee6; --field-line:#ebebe9;
  --btn-line:#eaeae9; --btn-ink:#243044;
  --card-line:#ecebe8;
  --gold-glow:rgba(201,169,97,.25);
  --gold-dim:rgba(201,169,97,.10);
